16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Text of the value terminator carried by the option whose terminator was
47	    // consumed as the previous closed word. It only lives for one word: a second
48	    // terminator is a duplicate (and therefore illegal) while any other word
49	    // resumes normal parsing.
50	    let mut last_terminator: Option<OsString> = None;
51	    // Set when an already closed word carried a value that cannot be part of
52	    // the command line (a delimiter-separated value set that is overfull, has
53	    // an empty segment, ...). Completion then reports "no completion generated"
54	    // instead of guessing at unrelated candidates.
55	    let mut is_illegal = false;
56	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
57	    // conflicting candidates. Only recognized option names are recorded;
58	    // values, positionals, `--`-escaped words, default values and env values
59	    // never are.
60	    let mut explicit_opts = HashSet::<Id>::new();
61	    while let Some(arg) = raw_args.next(&mut cursor) {
62	        let current_state = next_state;
63	        next_state = ParseState::ValueDone;
64	        debug!(
65	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
66	            arg.to_value_os(),
67	        );
68	        if cursor == target_cursor {
69	            if is_illegal {
70	                return Err(std::io::Error::other("no completion generated"));
71	            }
72	            // A terminator typed immediately after the standalone terminator
73	            // would be a second one; it closes no value and cannot complete.
74	            if last_terminator
75	                .as_deref()
76	                .is_some_and(|term| word_is(term, &arg))
77	            {
78	                return Err(std::io::Error::other("no completion generated"));
79	            }
80	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
81	            return complete_arg(
82	                &arg,
83	                current_cmd,
84	                current_dir,
85	                pos_index,
86	                is_escaped,
87	                current_state,
88	                &disabled,
89	            );
90	        }
91	
92	        // The terminator that ended the previous closed word, repeated here,
93	        // cannot close the occurrence a second time.
94	        let duplicate_terminator = last_terminator
95	            .as_deref()
96	            .is_some_and(|term| word_is(term, &arg));
97	        if duplicate_terminator {
98	            is_illegal = true;
99	        }
100	
101	        if let Ok(value) = arg.to_value() {
102	            // clap's parser probes for a subcommand only outside an ongoing
103	            // option value or multi-value positional, and never after `--`.
104	            // A word is therefore left to its level when a multi-value
105	            // positional is being filled or an option is still taking values
106	            // (including a dangling delimiter segment). The one-word `closed`
107	            // window of an option with a value terminator already finished the
108	            // occurrence, so it probes like an ordinary level.
109	            let filling_positional = matches!(current_state, ParseState::Pos(..));
110	            let taking_option_value =
111	                matches!(&current_state, ParseState::Opt(state) if !state.closed);
112	            if !is_escaped && !filling_positional && !taking_option_value {
113	                if let Some(next_cmd) = select_subcommand(current_cmd, value) {
114	                    current_cmd = next_cmd;
115	                    pos_index = 1;
116	                    last_terminator = None;
117	                    continue;
118	                }
119	            }
120	        }
121	
122	        // A standalone terminator word ends the option's value taking; it is
123	        // neither a value nor a candidate. It cannot arrive while a dangling
124	        // delimiter still expects a segment, before the option's minimum number
125	        // of value words is present, or after an earlier illegal word.
126	        let mut consumed_terminator: Option<OsString> = None;
127	        if let ParseState::Opt(state) = &current_state {
128	            if let Some(terminator) = state.opt.get_value_terminator() {
129	                if word_is(OsStr::new(terminator.as_str()), &arg) {
130	                    let min = state.opt.get_num_args().expect("built").min_values();
131	                    let consumed_words = state.word.saturating_sub(1);
132	                    if state.open || consumed_words < min || is_illegal {
133	                        is_illegal = true;
134	                    } else {
135	                        consumed_terminator = Some(OsString::from(terminator.as_str()));
136	                    }
137	                }
138	            }
139	        }
140	
141	        // While a dangling delimiter makes the next segment mandatory
142	        // (`--opt=a,`), a closed word may only be that segment.  An option
143	        // word (recognized or not) or `--` cannot fill it and clap rejects the
144	        // line, so completion reports an error instead of guessing a stop or a
145	        // new option. An option with `allow_hyphen_values` still accepts a
146	        // hyphen-prefixed word as the segment. A plain value word below is
147	        // consumed as the segment.
148	        if let ParseState::Opt(state) = &current_state {
149	            if state.open && !is_escaped && !opt_allows_hyphen(&current_state, &arg) {
150	                let is_option_word = arg.is_escape()
151	                    || arg.to_long().is_some()
152	                    || arg
153	                        .to_short()
154	                        .is_some_and(|short| !short.is_negative_number());
155	                if is_option_word {
156	                    is_illegal = true;
157	                }
158	            }
159	        }
160	
161	        // Once the value occurrence is complete, only the standalone terminator
162	        // still belongs to it; any other word resumes ordinary option/positional
163	        // parsing. This one-word window makes the terminator work identically
164	        // across `=`, separate words, shorts and aliases.
165	        let dispatch_state = if matches!(&current_state, ParseState::Opt(state) if state.closed)
166	            && consumed_terminator.is_none()
167	        {
168	            ParseState::ValueDone
169	        } else {
170	            current_state
171	        };
172	
173	        if is_escaped {
174	            let accepted = closed_positional_is_accepted(current_cmd, pos_index, arg.to_value_os());
175	            (next_state, pos_index) =
176	                parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
177	            if !accepted {
178	                // After `--`, clap accepts only positional values (and
179	                // directory entries for path arguments); a word the slot
180	                // rejects makes the whole line uncompletable.
181	                is_illegal = true;
182	            }
183	        } else if arg.is_escape() {
184	            is_escaped = true;
185	        } else if consumed_terminator.is_some() {
186	            next_state = ParseState::ValueDone;
187	        } else if opt_allows_hyphen(&dispatch_state, &arg) {
188	            match dispatch_state {
189	                ParseState::Opt(state) => {
190	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
191	                }
192	                _ => unreachable!("else branch is only reachable in Opt state"),
193	            }
194	        } else if let Some((flag, value)) = arg.to_long() {
195	            if let Ok(flag) = flag {
196	                let opt = current_cmd.get_arguments().find(|a| {
197	                    let longs = a.get_long_and_visible_aliases();
198	                    let is_find = longs.map(|v| {
199	                        let mut iter = v.into_iter();
200	                        let s = iter.find(|s| *s == flag);
201	                        s.is_some()
202	                    });
203	                    is_find.unwrap_or(false)
204	                });
205	
206	                if let Some(opt) = opt {
207	                    explicit_opts.insert(opt.get_id().clone());
208	                    if opt.get_num_args().expect("built").takes_values() {
209	                        match value {
210	                            // A bare `--name` still expects its value as the next word.
211	                            None => next_state = ParseState::Opt(OptState::new(opt, 1)),
212	                            // A closed `--name=value` word normally ends the
213	                            // occurrence, but a dangling value delimiter with
214	                            // room for another segment keeps accepting values.
215	                            Some(value) => {
216	                                next_state = attached_opt_state(opt, value, &mut is_illegal);
217	                            }
218	                        }
219	                    }
220	                } else if pos_allows_hyphen(current_cmd, pos_index) {
221	                    let accepted =
222	                        closed_positional_is_accepted(current_cmd, pos_index, arg.to_value_os());
223	                    (next_state, pos_index) =
224	                        parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
225	                    if !accepted {
226	                        is_illegal = true;
227	                    }
228	                } else {
229	                    // A closed word with a `--name`/`--name=value` shape that
230	                    // names no option cannot be part of a valid command line;
231	                    // clap reports an unknown argument.
232	                    is_illegal = true;
233	                }
234	            } else if !pos_allows_hyphen(current_cmd, pos_index) {
235	                is_illegal = true;
236	            }
237	        } else if let Some(short) = arg.to_short() {
238	            let (leading_flags, takes_value_opt, mut short, cluster_valid) =
239	                parse_shortflags(current_cmd, short);
240	            // Only a cluster made entirely of recognized flags records state.
241	            // Splitting an invalid short string into known and unknown members
242	            // would be guesswork and could suppress conflicting candidates, so
243	            // invalid clusters keep the existing completion behavior; clap's
244	            // parser would reject them anyway.
245	            if cluster_valid {
246	                // Every recognized flag in the cluster was explicitly supplied.
247	                for flag in leading_flags.chars() {
248	                    if let Some(opt) = current_cmd.get_arguments().find(|a| {
249	                        a.get_short_and_visible_aliases()
250	                            .is_some_and(|shorts| shorts.contains(&flag))
251	                    }) {
252	                        explicit_opts.insert(opt.get_id().clone());
253	                    }
254	                }
255	            }
256	            if let Some(opt) = takes_value_opt {
257	                if let Some(remainder) = short.next_value_os() {
258	                    // A closed `-ovalue` / `-o=value` word; advance like the
259	                    // long `--opt=value` form.
260	                    let value = remainder.strip_prefix("=").unwrap_or(remainder);
261	                    next_state = attached_opt_state(opt, value, &mut is_illegal);
262	                } else {
263	                    next_state = ParseState::Opt(OptState::new(opt, 1));
264	                }
265	            } else if pos_allows_hyphen(current_cmd, pos_index) {
266	                let accepted =
267	                    closed_positional_is_accepted(current_cmd, pos_index, arg.to_value_os());
268	                (next_state, pos_index) =
269	                    parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
270	                if !accepted {
271	                    is_illegal = true;
272	                }
273	            }
274	            // An invalid short cluster (an unknown member, or no
275	            // value-taking option) deliberately keeps the legacy completion
276	            // behavior rather than flagging the line: its members are not
277	            // guessed apart, and the cursor word still completes on this
278	            // level.
279	        } else {
280	            match dispatch_state {
281	                ParseState::ValueDone | ParseState::Pos(..) => {
282	                    let accepted =
283	                        closed_positional_is_accepted(current_cmd, pos_index, arg.to_value_os());
284	                    (next_state, pos_index) =
285	                        parse_positional(current_cmd, pos_index, is_escaped, dispatch_state);
286	                    if !accepted {
287	                        // The word names no subcommand and the current
288	                        // positional slot does not accept it, so clap would
289	                        // reject the line. Completion must not guess a split or
290	                        // keep offering parent-level candidates.
291	                        is_illegal = true;
292	                    }
293	                }
294	                ParseState::Opt(state) => {
295	                    next_state = advance_opt_value(state, arg.to_value_os(), &mut is_illegal);
296	                }
297	            }
298	        }
299	
300	        // Remember a just-consumed terminator for exactly one word so a
301	        // repeated terminator is flagged as a duplicate; every other word
302	        // clears it and resumes ordinary parsing.
303	        last_terminator = consumed_terminator;
304	    }
305	
306	    Err(std::io::Error::other("no completion generated"))
307	}
