798	/// Generate value candidates for the segment under the cursor of a
799	/// delimiter-separated multi-value option.
800	///
801	/// `prior_segments` is the number of segments already closed by earlier shell
802	/// words; `prior_used` are their literal values, suppressed from the result so
803	/// an already selected value is not offered a second time.  Candidates cover
804	/// only the current shell word, so `prefix` from closed segments is limited to
805	/// the current word as well.
806	///
807	/// `Ok` carries the candidates; `Err(())` marks an illegal segment position
808	/// (an empty segment or a segment past the accepted number of values).
809	fn complete_segment_value(
810	    value: &OsStr,
811	    opt: &clap::Arg,
812	    prior_segments: usize,
813	    prior_used: &[&OsStr],
814	    arg_index: usize,
815	    current_dir: Option<&std::path::Path>,
816	) -> Result<Vec<CompletionCandidate>, ()> {
817	    // For a bounded delimiter option with a fixed value set, the terminator is
818	    // recognized only as a standalone word; glued onto a segment (`--opt=a;`,
819	    // `--opt=;`) it cannot be part of a valid line and the engine never guesses
820	    // a split. A free-form option takes the whole word, like clap's parser.
821	    if glued_terminator_is_illegal(opt) {
822	        if let Some(terminator) = opt.get_value_terminator() {
823	            if value.contains(terminator.as_str()) {
824	                return Err(());
825	            }
826	        }
827	    }
828	    let Some(cursor) = cursor_delimited(opt, value, prior_segments)? else {
829	        // Not a bounded delimiter option: keep the legacy whole-word
830	        // completion (its own `rsplit_delimiter` handles single-value args).
831	        return Ok(complete_arg_value(
832	            value.to_str().ok_or(value),
833	            opt,
834	            current_dir,
835	            arg_index,
836	        ));
837	    };
838	
839	    let mut used: Vec<&OsStr> = prior_used.to_vec();
840	    used.extend(cursor.closed.iter().copied());
841	
842	    let mut values = complete_arg_value(
843	        Ok(cursor.current.to_str().ok_or(())?),
844	        opt,
845	        current_dir,
846	        arg_index,
847	    );
848	    // An already closed segment stays selected and must not reappear.
849	    values.retain(|comp| !used.iter().any(|u| *u == comp.get_value()));
850	    if !cursor.prefix.is_empty() {
851	        values = values
852	            .into_iter()
853	            .map(|comp| comp.add_prefix(cursor.prefix))
854	            .collect();
855	    }
856	    Ok(values)
857	}
