859	/// Completion at a space-separated option value word tracked by `state`.
860	fn complete_separate_opt_value(
861	    value: Result<&str, &OsStr>,
862	    state: &OptState<'_>,
863	    current_dir: Option<&std::path::Path>,
864	) -> Result<Vec<CompletionCandidate>, ()> {
865	    let value_os = match value {
866	        Ok(value) => OsStr::new(value),
867	        Err(value_os) => value_os,
868	    };
869	    let used: Vec<&OsStr> = state.used.iter().map(OsString::as_os_str).collect();
870	    complete_segment_value(
871	        value_os,
872	        state.opt,
873	        state.used.len(),
874	        &used,
875	        state.word.saturating_sub(1),
876	        current_dir,
877	    )
878	}
