1564	/// Arguments that must not be offered because they conflict with an explicitly
1565	/// present option. The present options themselves are never disabled.
1566	fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
1567	    let mut disabled = HashSet::new();
1568	    if explicit.is_empty() {
1569	        return disabled;
1570	    }
1571	    for arg in cmd.get_arguments() {
1572	        if explicit.contains(arg.get_id()) {
1573	            // A present option hides everything it conflicts with ...
1574	            for id in arg_direct_conflicts(cmd, arg) {
1575	                if !explicit.contains(&id) {
1576	                    disabled.insert(id);
1577	                }
1578	            }
1579	        } else {
1580	            // ... and is hidden when either side declares the conflict.
1581	            if arg_direct_conflicts(cmd, arg)
1582	                .iter()
1583	                .any(|id| explicit.contains(id))
1584	            {
1585	                disabled.insert(arg.get_id().clone());
1586	            }
1587	        }
1588	    }
1589	    disabled
1590	}
1591	
1592	/// Conflict partners of `arg`, following the same rules as clap's parser:
1593	/// - the argument's own `conflicts_with` / `conflicts_with_all`
1594	/// - `conflicts_with` / `conflicts_with_all` of every group the argument belongs to
1595	/// - the other members of non-`multiple` groups
1596	///
1597	/// Group ids are expanded to their argument members.
1598	/// `overrides_with` relationships are intentionally not considered.
1599	fn arg_direct_conflicts(cmd: &clap::Command, arg: &clap::Arg) -> HashSet<Id> {
1600	    let mut conflicts = arg
1601	        .get_conflicts_with()
1602	        .map(ToOwned::to_owned)
1603	        .collect::<HashSet<_>>();
1604	    for group in cmd.get_groups() {
1605	        let members = unroll_group(cmd, group.get_id());
1606	        if !members.iter().any(|m| m == arg.get_id()) {
1607	            continue;
1608	        }
1609	        conflicts.extend(group.get_conflicts_with().map(ToOwned::to_owned));
1610	        if !group.is_multiple_set() {
1611	            conflicts.extend(members.into_iter().filter(|m| m != arg.get_id()));
1612	        }
1613	    }
1614	    conflicts
1615	        .iter()
1616	        .flat_map(|id| unroll_group(cmd, id))
1617	        .collect()
1618	}
1619	
1620	/// Resolve an argument or group id to its argument members.
1621	/// Unknown ids resolve to themselves.
1622	fn unroll_group(cmd: &clap::Command, id: &Id) -> Vec<Id> {
1623	    let mut pending = vec![id.clone()];
1624	    let mut args = Vec::new();
1625	    while let Some(id) = pending.pop() {
1626	        if cmd.get_arguments().any(|a| a.get_id() == &id) {
1627	            if !args.contains(&id) {
1628	                args.push(id);
1629	            }
1630	        } else if let Some(group) = cmd.get_groups().find(|g| g.get_id() == &id) {
1631	            pending.extend(group.get_args().map(ToOwned::to_owned));
1632	        } else if !args.contains(&id) {
1633	            args.push(id);
1634	        }
1635	    }
1636	    args
1637	}
