use std::ffi::OsString;

use clap::Command;

fn tool() -> Command {
    Command::new("tool")
        .arg(
            clap::Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(clap::ArgAction::SetTrue),
        )
        .arg(
            clap::Arg::new("number")
                .short('n')
                .long("number")
                .value_parser(["-3", "-2", "-1", "0", "1", "2", "3"]),
        )
        .arg(
            clap::Arg::new("mode")
                .long("mode")
                .short('m')
                .value_parser(["fast", "safe"]),
        )
        .arg(clap::Arg::new("path").value_hint(clap::ValueHint::DirPath))
}

fn run(input: &str) {
    let mut parts: Vec<&str> = input.split_whitespace().collect();
    let cursor_empty = input.ends_with(' ');
    let mut args: Vec<OsString> = vec!["tool".into()];
    args.extend(parts.iter().map(|s| OsString::from(*s)));
    if cursor_empty {
        args.push("".into());
    }
    let arg_index = args.len() - 1;
    let mut cmd = tool();
    match clap_complete::engine::complete(&mut cmd, args, arg_index, None) {
        Ok(cs) => {
            let vals: Vec<_> = cs.iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect();
            println!("OK   {:<30} => {:?}", input, vals);
        }
        Err(e) => println!("ERR  {:<30} => {}", input, e),
    }
}

