        "-n ",              // 4
        "-n-",              // 5
        "-n-3 ",            // 6
        "-vn-3 ",           // 7
        "--number=-3 ",     // 8
        "--number -3 ",     // 9
        "-n -3 ",           // 10
        "-n3v",             // 11
        "-n-3v",            // 12
        "-n3v ",            // 13 closed
        "-n-3v ",           // 14 closed
        "-v3 ",             // 15
        "-vv",              // 16 cursor
        "-vv ",             // 17 closed
        "-x",               // 18
        "-x ",              // 19
        "-n9 ",             // 20 illegal number closed
        "-n9",              // 21 cursor
        "-n ",              // 22
        "-n --mode fast ",  // 23 missing value
        "-n3 ",             // 24 done
        "-n3 -m fast ",     // 25
        "-- ",              // 26
        "-- -v ",           // 27
        "-",                // 28 empty cluster cursor
        "-3",               // 29 root negative number cursor
        "-3 ",              // 30 closed
        "9 ",               // 31 positional number
        "-vn ",             // dup
        "-n-3 -",           // 32 after value, "-" cursor
        "-n -",             // 33
        "-n=",              // 34
