/// Whether the value under the cursor glues extra text onto a complete fixed
/// possible value, e.g. `3v` or `-3v` when `3`/`-3` are already complete
/// values. clap rejects such a word rather than splitting the value from more
/// flags. A plain prefix with no match (`9`) still completes as an empty
/// candidate list instead.
fn glued_fixed_value_is_illegal(opt: &clap::Arg, value: &OsStr) -> bool {
    if opt.get_value_delimiter().is_some() {
        return false;
    }
    let Some(possible) = possible_values(opt) else {
        return false;
    };
    let Ok(value) = value.to_str() else {
        return false;
    };
    if value.is_empty() {
        return false;
    }
    let ignore_case = opt.is_ignore_case_set();
    let possible: Vec<_> = possible.collect();
    if possible.iter().any(|pv| pv.matches(value, ignore_case)) {
        // Still editing this exact value.
        return false;
    }
    if possible.iter().any(|pv| value.starts_with(pv.get_name())) {
        // Text continues past a complete value: no completion can repair it.
        return true;
    }
    false
}

