    let path = testdir.path().unwrap();
    fs::create_dir_all(path.join("a_dir/nested")).unwrap();
    fs::create_dir_all(path.join("b_dir")).unwrap();
    fs::write(path.join("a_file"), "").unwrap();

    let cases = [
        "-[TAB]",
        "-v -[TAB]",
        "-vn-3 -[TAB]",
        "-- [TAB]",
        "-v -- [TAB]",
        "-- a[TAB]",
        "-- b_dir [TAB]",
        "-v[TAB]",
        "-n[TAB]",
        "-vn-",
        "-n3v[TAB]",
        "-n30[TAB]",
        "-9[TAB]",
        "-[TAB]",
        "x -[TAB]",
    ];
    for input in cases {
        let mut cmd = tool();
        let mut s = String::from("tool ");
        s.push_str(input);
        let out = complete_str(&mut cmd, &s, Some(path));
        println!("### {input}\n{out}<<<");
    }
}

fn complete_str(
    cmd: &mut clap::Command,
    input: &str,
    dir: Option<&std::path::Path>,
) -> String {
    let body = input.trim_start_matches("tool ");
    let mut args = vec![std::ffi::OsString::from("tool")];
    if let Some((prior, after)) = body.split_once("[TAB]") {
        args.extend(prior.split_whitespace().map(std::ffi::OsString::from));
        if prior.ends_with(char::is_whitespace) {
            args.push(std::ffi::OsString::default());
        }
        let arg_index = args.len() - 1;
        args.extend(after.split_whitespace().map(std::ffi::OsString::from));
        clap_complete::engine::complete(cmd, args, arg_index, dir)
    } else {
        args.extend(body.split_whitespace().map(std::ffi::OsString::from));
        if body.ends_with(char::is_whitespace) {
            args.push(std::ffi::OsString::default());
        }
        let arg_index = args.len() - 1;
        clap_complete::engine::complete(cmd, args, arg_index, dir)
    }
    .map(|cs| {
        cs.into_iter()
            .map(|c| {
                let v = c.get_value().to_str().unwrap();
                match c.get_help() {
                    Some(h) => format!("{v}\t{h}"),
                    None => v.to_owned(),
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    })
    .unwrap_or_else(|e| format!("ERR: {e}"))
}

