/// Arguments that must not be offered because they conflict with an explicitly
/// present option. The present options themselves are not disabled here: while
/// an option's own value is being completed it must still offer its values.
/// Option-name listings additionally hide a non-repeatable option that has
/// already been consumed (see [`option_name_disabled`]).
fn gather_disabled_args(cmd: &clap::Command, explicit: &HashSet<Id>) -> HashSet<Id> {
    let mut disabled = HashSet::new();
    if explicit.is_empty() {
        return disabled;
    }
    for arg in cmd.get_arguments() {
        if explicit.contains(arg.get_id()) {
            // A present option hides everything it conflicts with ...
            for id in arg_direct_conflicts(cmd, arg) {
                if !explicit.contains(&id) {
                    disabled.insert(id);
                }
            }
        } else {
            // ... and is hidden when either side declares the conflict.
            if arg_direct_conflicts(cmd, arg)
                .iter()
                .any(|id| explicit.contains(id))
            {
                disabled.insert(arg.get_id().clone());
            }
        }
    }
    disabled
}

/// Ids to hide from *option-name* listings: every conflicting argument plus a
/// non-repeatable option that already occurred (a second occurrence is invalid,
/// so its name is not offered again). `Count`/`Append` options stay listed.
fn option_name_disabled(
    cmd: &clap::Command,
    disabled: &HashSet<Id>,
    explicit: &HashSet<Id>,
) -> HashSet<Id> {
    let mut hidden = disabled.clone();
    for arg in cmd.get_arguments() {
        if explicit.contains(arg.get_id()) && !arg_is_repeatable(arg) {
            hidden.insert(arg.get_id().clone());
        }
    }
    hidden
}

