// Offer this waiting option's own values. When it is disabled, it
// is usually because it conflicts with an option already present
// (clap rejects the line regardless), so its values stay hidden;
// the single exception is its own recorded spelling while the
// cursor is still at its value position, e.g. a bare `-n`.
let conflicts_with_present = arg_direct_conflicts(cmd, opt)
    .iter()
    .any(|id| id != opt.get_id() && disabled.contains(id));
if !disabled.contains(opt.get_id()) || !conflicts_with_present {
    match complete_separate_opt_value(arg.to_value(), &state, current_dir) {
        Ok(values) => completions.extend(values),
        // The cursor sits at an illegal segment position (an empty
        // segment or one past the accepted number of values).
        Err(()) => return Err(std::io::Error::other("no completion generated")),
    }
}

